            if (memcmp(item->type, "av01", 4) && !isGrid) {
                // probably exif or some other data
                continue;
            }
            if (item->thumbnailForID != 0) {
                // It's a thumbnail, skip it
                continue;
            }
            if ((data->meta->primaryItemID > 0) && (item->id != data->meta->primaryItemID)) {
                // a primary item ID was specified, require it
                continue;
            }

            if (isGrid) {
                if (decoder->disableGridImages) {
                    return AVIF_RESULT_BMFF_PARSE_FAILED;
                }

                avifROData readData;
                avifResult readResult = avifDecoderReadItem(decoder, item, &readData, 0);
                if (readResult != AVIF_RESULT_OK) {
                    return readResult;
                }
                if ((readData.data == NULL) || (readData.size != item->size)) {
                    return AVIF_RESULT_BMFF_PARSE_FAILED;
                }
                if (!avifParseImageGridBox(&data->colorGrid, readData.data, item->size)) {
                    return AVIF_RESULT_INVALID_IMAGE_GRID;
                }
            }

            colorItem = item;
            break;
